def transform(grid):
    """Color the largest 4-connected zero region 8 and the smallest 7."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    regions = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            region = []
            while q:
                y, x = q.popleft()
                region.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            regions.append(region)

    if len(regions) >= 2:
        smallest = min(regions, key=len)
        largest = max(regions, key=len)
        for r, c in smallest:
            out[r][c] = 7
        for r, c in largest:
            out[r][c] = 8
    return out
